1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  rune: 250,
63	};
64	
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	const CAP_MULTIPLIER = 2;
67	
68	const ALIKE_BLOCK_SIZE = 3;
69	const ALIKE_BLOCK_PREMIUM = 60;
70	
71	type AlikeGroup = [type: string, count: number];
72	
73	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
74	  const countByType = new Map<string, number>();
75	
76	  for (const item of items) {
77	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
78	  }
79	
80	  return [...countByType];
81	};
82	
83	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
84	
85	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
86	
87	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
88	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
89	
90	  return count * basePremiumOfType(type);
91	};
92	
93	/**
94	 * The policy base premium: the sum of the item base premiums, with the
95	 * alike-block discount applied. Policy-scope modifiers are percentages OF
96	 * THIS amount — never of a total that already includes item surcharges.
97	 */
98	const policyBasePremiumOf = (items: Item[]): number =>
99	  groupAlikeItems(items)
100	    .map(basePremiumOfGroup)
101	    .reduce((total, groupPremium) => total + groupPremium, 0);
102	
103	/**
104	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
105	 * premium, independent of the policy base and of the alike-block discount.
106	 */
107	const isCursed = (item: Item): boolean => item.cursed === true;
108	
109	const isHighlyEnchanted = (item: Item): boolean =>
110	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
111	
112	const itemSurchargeRateOf = (item: Item): number =>
113	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
114	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
115	
116	const itemSurchargesOf = (items: Item[]): number =>
117	  items.reduce(
118	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
119	    0,
120	  );
121	
122	/**
123	 * Policy-scope modifiers: each is a percentage of the policy base premium.
124	 * Surcharges and discounts are netted into a single rate, so the policy base is
125	 * multiplied exactly once — this keeps the result free of the rounding drift
126	 * that separate discount and surcharge terms would introduce. The netted rate
127	 * (and hence the returned amount) is negative when the discounts outweigh the
128	 * surcharges.
129	 */
130	const isLongStanding = (customer: Customer): boolean =>
131	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
132	
133	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
134	  FIRST_INSURANCE_SURCHARGE -
135	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
136	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
137	
138	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
139	  policyBase * policyModifierRateOf(policy);
140	
141	const quotePremium = (items: Item[], policy: Policy): number => {
142	  const policyBase = policyBasePremiumOf(items);
143	  const premium =
144	    policyBase +
145	    itemSurchargesOf(items) +
146	    policyModifiersOn(policyBase, policy) +
147	    PROCESSING_FEE;
148	
149	  return Math.ceil(premium);
150	};
151	
152	/**
153	 * Whether any step precedes this one. A quote is a follow-up contract when the
154	 * customer already holds one, and today every step is a quote — so "has a
155	 * predecessor" and "is a follow-up contract" coincide.
156	 *
157	 * They stop coinciding once claim steps exist: a claim at index 0 would make
158	 * the quote at index 1 look like a follow-up. At that point the caller must
159	 * count preceding QUOTE steps instead of asking this. The name is deliberately
160	 * about position, not contracts, so that the substitution is a visible change
161	 * at the call site rather than a silent redefinition here.
162	 */
163	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
164	
165	const insuranceSumOf = (items: Item[]): number =>
166	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
167	
168	const payoutForDamage = (damage: Damage): number =>
169	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
170	
171	/**
172	 * The quote step a claim is filed against. Today this ASSUMES the referenced
173	 * index holds a quote: nothing has forced the assumption to be checked yet, and
174	 * a claim naming a non-quote step fails here with an opaque undefined-property
175	 * error rather than a rejection.
176	 *
177	 * The assumption is isolated in this function on purpose. The pending
178	 * error-handling tests ("a claim for an item not part of the policy", "a claim
179	 * with a damage entry of an unknown item type") are what will force a real
180	 * rejection, and this is the single place that has to change when they do.
181	 */
182	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
183	  steps[claim.policy] as QuoteStep;
184	
185	const settleClaim = (claim: ClaimStep, steps: Step[]): ClaimResult => {
186	  const policy = policyReferencedBy(claim, steps);
187	  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
188	  const payout = claim.incident.damages.reduce(
189	    (total, damage) => total + payoutForDamage(damage),
190	    0,
191	  );
192	
193	  return { payout, remainingCap: cap - payout };
194	};
195	
196	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
197	  results: scenario.steps.map((step, stepIndex) =>
198	    isQuoteStep(step)
199	      ? {
200	          premium: quotePremium(step.items, {
201	            customer: scenario.customer,
202	            isFollowUpContract: hasPrecedingStep(stepIndex),
203	          }),
204	        }
205	      : settleClaim(step, scenario.steps),
206	  ),
207	});
